import { createRequire } from 'node:module';
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const root='<USER_HOME>/project/team-task-board/frontend';
const require=createRequire(root+'/package.json');
const { chromium }=require('@playwright/test');
const server=spawn(process.execPath,[root+'/node_modules/vite/bin/vite.js','--host','127.0.0.1','--port','5182','--strictPort'],{cwd:root,stdio:['ignore','pipe','pipe']});
let logs=''; server.stdout.on('data',x=>logs+=x);server.stderr.on('data',x=>logs+=x);
let browser; const results=[];
function luminance(rgb){const c=rgb.map(x=>{x/=255;return x<=0.04045?x/12.92:((x+0.055)/1.055)**2.4});return .2126*c[0]+.7152*c[1]+.0722*c[2]}
function ratio(a,b){const l=[luminance(a),luminance(b)].sort((a,b)=>b-a);return (l[0]+.05)/(l[1]+.05)}
try{
 let ready=false;
 for(let i=0;i<100;i++){if(server.exitCode!==null)throw Error('own server exited: '+logs);try{const r=await fetch('http://127.0.0.1:5182');if(r.ok){ready=true;break}}catch{} await new Promise(r=>setTimeout(r,100));}
 if(!ready)throw Error('server not ready');
 browser=await chromium.launch();
 for(const theme of ['light','dark'])for(const width of [1440,390]){
 const page=await browser.newPage({colorScheme:theme,viewport:{width,height:1000}});let failed=false;
 await page.route('**/api/tasks',route=>route.fulfill({status:failed?500:200,json:failed?{message:'retry'}:[{id:'review-task',title:'contrast review',description:'fixture',assignee:'review',status:'TODO',createdAt:'2026-10-06T00:00:00Z',version:0}]}));
 await page.goto('http://127.0.0.1:5182');await page.getByRole('article').waitFor();
 async function inspect(state){for(const selector of ['.brand-mark','.search > span[aria-hidden="true"]']){
 const el=page.locator(selector);if(!await el.isVisible())continue;
 const d=await el.evaluate(e=>{const s=getComputedStyle(e);const chain=[];for(let p=e;p;p=p.parentElement){const c=getComputedStyle(p);chain.push({tag:p.tagName,color:c.backgroundColor,image:c.backgroundImage,opacity:c.opacity,filter:c.filter});}return {selector:e.className,text:e.textContent,foreground:s.color,chain,fontSize:s.fontSize,ariaHidden:e.getAttribute('aria-hidden')};});
 const fg=d.foreground.match(/[\d.]+/g).map(Number);if(fg.length>3&&fg[3]!==1)throw Error('unsupported translucent foreground');
 const bgNode=d.chain.find(c=>{const n=c.color.match(/[\d.]+/g).map(Number);return n.length===3||n[3]===1});if(!bgNode)throw Error('opaque background absent');
 const bg=bgNode.color.match(/[\d.]+/g).map(Number);for(const c of d.chain.slice(0,d.chain.indexOf(bgNode)+1)){if(c.image!=='none'||c.opacity!=='1'||c.filter!=='none')throw Error('unsupported paint effect');}
 const value=ratio(fg.slice(0,3),bg.slice(0,3));if(value<4.5)throw Error('conservative contrast threshold failed: '+value);
 results.push({theme,width,state,selector,...d,background:bgNode.color,contrastRatio:value,threshold:4.5,verdict:'PASS'});
 }}
 await inspect('board');await page.getByRole('button',{name:'수정',exact:true}).click();await inspect('edit');await page.getByRole('button',{name:'취소',exact:true}).click();failed=true;await page.getByRole('button',{name:'새로고침',exact:true}).click();await page.getByRole('alert').waitFor();await inspect('error');await page.close();
 }
 writeFileSync('/tmp/harness-contrast-review-result.json',JSON.stringify({command:'node /tmp/harness-contrast-review.mjs',cwd:root,port:5182,mockedList:true,results},null,2));
 console.log(JSON.stringify({observations:results.length,minContrast:Math.min(...results.map(r=>r.contrastRatio)),pairs:[...new Set(results.map(r=>r.selector+' '+r.theme+' '+r.contrastRatio))]},null,2));
}finally{if(browser)await browser.close();server.kill('SIGTERM');await new Promise(resolve=>{if(server.exitCode!==null)resolve();else server.once('exit',resolve)});}
